// Generated by Cypress Author on 2026-11-02.
// Business snapshots deliberately exclude sessions and last_login. Every test starts
// with synthetic fixtures; no production database or real contact data is used.
const copy = {
  en: { schedule: 'Barbers schedules', mine: 'My services', add: 'Add barber', manage: 'Manage services', hours: 'Hours & days off', edit: 'Edit profile', show: 'Show', previous: 'Previous', next: 'Next', logout: 'Sign out' },
  bg: { schedule: 'График на бръснарите', mine: 'Моите услуги', add: 'Добави бръснар', manage: 'Управлявай услугите', hours: 'Работно време и почивки', edit: 'Редактирай профила', show: 'Покажи', previous: 'Назад', next: 'Напред', logout: 'Изход' },
};

function openStaff(role = 'owner') {
  cy.login(role);
  cy.setLanguage('en');
}

function submit(label) {
  cy.contains('main button', label).click();
}

function unchangedExcept(before, after, keys) {
  Object.keys(before).filter((key) => !keys.includes(key)).forEach((key) => {
    expect(after[key], `${key} unchanged`).to.deep.equal(before[key]);
  });
}

function noOverflow() {
  cy.document().then((document) => {
    expect(document.documentElement.scrollWidth, 'page fits viewport').to.be.at.most(document.documentElement.clientWidth + 1);
  });
}

describe('Staff navigation, roles, languages and viewports', () => {
  for (const language of ['en', 'bg']) {
    for (const viewport of [[1440, 1000], [390, 844]]) {
      for (const role of ['owner', 'alan']) {
        it(`${role}, ${language}, ${viewport[0]}px: every navigation action preserves business rows and colleague privacy`, () => {
          cy.viewport(...viewport);
          cy.login(role);
          cy.setLanguage(language);
          cy.task('db:snapshot').then((before) => {
            cy.get('@seed').then((seed) => {
              const labels = copy[language];
              cy.visit('/staff/');
              cy.get('html').should('have.attr', 'lang', language);
              noOverflow();
              const capture = (language === 'en' && role === 'owner' && viewport[0] === 1440) || (language === 'bg' && role === 'alan' && viewport[0] === 390);
              if (capture) cy.screenshot(`dashboard-${role}-${language}-${viewport[0]}`, { capture: 'viewport' });
              cy.get('header a[href="/book/"]').click();
              cy.location('pathname').should('eq', '/book/');
              cy.get('header a[href="/staff/"]').click();
              cy.location('pathname').should('eq', '/staff/');
              cy.get(`header a[lang="${language === 'en' ? 'bg' : 'en'}"]`).click();
              cy.get('html').should('have.attr', 'lang', language === 'en' ? 'bg' : 'en');
              cy.get(`header a[lang="${language}"]`).click();
              cy.get('html').should('have.attr', 'lang', language);
              if (role === 'owner') {
                cy.contains('a', labels.add).click();
                cy.location('pathname').should('eq', '/staff/barbers/new/');
                cy.get('[name="password"]').should('have.attr', 'required');
                cy.get('[name^="open_"]').should('have.length', 7).and('be.checked');
                cy.visit('/staff/');
                cy.contains('a', labels.manage).click();
                cy.location('pathname').should('eq', '/staff/services/');
                cy.get(`a[href="/staff/services/${seed.services.cut}/"]`).click();
                cy.get('[name="name"]').should('have.value', 'Audit Haircut');
                cy.visit('/staff/');
                cy.get(`a[href="/staff/barbers/${seed.barbers.alan}/"]`).click();
                cy.get('[name="username"]').should('have.value', 'alan');
                cy.get('[name="password"]').should('have.value', '');
              } else {
                cy.contains('a', labels.add).should('not.exist');
                cy.contains('a', labels.manage).should('not.exist');
                cy.get(`a[href="/staff/barbers/${seed.barbers.boris}/hours/"]`).should('not.exist');
                cy.contains('a', labels.mine).click();
                cy.location('pathname').should('eq', '/staff/my-services/');
                cy.get(`input[name="services"][value="${seed.services.inactive}"]`).should('be.checked');
                cy.get('main a[href="/staff/"]').click();
                cy.location('pathname').should('eq', '/staff/');
              }
              cy.visit('/staff/');
              cy.get(`a[href="/staff/barbers/${seed.barbers.alan}/hours/"]`).click();
              cy.get('[name^="open_"]').should('have.length', 7);
              noOverflow();
              if (capture) cy.screenshot(`hours-${role}-${language}-${viewport[0]}`, { capture: 'viewport' });
              cy.visit('/staff/');
              cy.contains('a', labels.schedule).click();
              cy.get('[name="date"]').clear().type(seed.date);
              cy.get('#barber-filter').select('');
              cy.get('#view-filter').select('day');
              submit(labels.show);
              cy.get('#view-filter').should('have.value', 'day');
              cy.contains('Synthetic alan client').should('be.visible');
              cy.get('a[href="tel:+359888000001"]').should('be.visible');
              cy.get(`form[action="/staff/appointments/${seed.appointments.alan.id}/cancel/"]`).should('exist');
              if (role === 'owner') {
                cy.contains('Synthetic boris client').should('be.visible');
                cy.get(`form[action="/staff/appointments/${seed.appointments.boris.id}/cancel/"]`).should('exist');
              } else {
                cy.contains('Synthetic boris client').should('not.exist');
                cy.get('main').should('not.contain', '+359888000002').and('not.contain', 'boris@example.invalid');
                cy.get(`form[action="/staff/appointments/${seed.appointments.boris.id}/cancel/"]`).should('not.exist');
                cy.contains(language === 'en' ? 'Booked' : 'Заето').should('be.visible');
              }
              noOverflow();
              if (capture) cy.screenshot(`schedule-${role}-${language}-${viewport[0]}`, { capture: 'viewport' });
              cy.get('#barber-filter').select(String(seed.barbers.alan));
              cy.get('#view-filter').select('week');
              submit(labels.show);
              cy.get('main h2').should('contain', 'Audit Alan').and('not.contain', 'Audit Boris');
              cy.contains('a', labels.previous).click();
              cy.get('[name="date"]').should('not.have.value', seed.date);
              cy.contains('a', labels.next).click();
              cy.get('[name="date"]').should('have.value', seed.date);
              cy.get('#barber-filter').should('have.value', String(seed.barbers.alan));
              cy.get('#view-filter').should('have.value', 'week');
              cy.get(`main a[href="/staff/barbers/${seed.barbers.alan}/hours/"]`).click();
              cy.location('pathname').should('eq', `/staff/barbers/${seed.barbers.alan}/hours/`);
              cy.contains('button', labels.logout).click();
              cy.location('pathname').should('eq', '/');
              cy.visit('/staff/');
              cy.location('pathname').should('eq', '/staff/login/');
              cy.assertNoBusinessChange(before);
            });
          });
        });
      }
    }
  }

  it('Barber, outsider and owner-only paths → unauthorized requests cannot change data', () => {
    openStaff('alan');
    cy.get('@seed').then((seed) => {
      cy.task('db:snapshot').then((before) => {
        for (const url of ['/staff/services/', '/staff/services/new/', '/staff/barbers/new/', `/staff/barbers/${seed.barbers.boris}/`, `/staff/barbers/${seed.barbers.boris}/hours/`]) {
          cy.request({ url, failOnStatusCode: false }).its('status').should('eq', 403);
        }
        cy.visit(`/staff/barbers/${seed.barbers.alan}/hours/`);
        cy.getCookie('csrftoken').then(({ value }) => {
          cy.request({ method: 'POST', url: `/staff/appointments/${seed.appointments.boris.id}/cancel/`, form: true, body: { csrfmiddlewaretoken: value }, failOnStatusCode: false }).its('status').should('eq', 403);
          cy.request({ method: 'POST', url: `/staff/barbers/${seed.barbers.boris}/hours/`, form: true, body: { csrfmiddlewaretoken: value, action: 'add_off', date: seed.nextDate }, failOnStatusCode: false }).its('status').should('eq', 403);
        });
        cy.login('owner');
        cy.request({ url: '/staff/my-services/', failOnStatusCode: false }).its('status').should('eq', 403);
        cy.login('outsider');
        cy.request({ url: '/staff/', failOnStatusCode: false }).its('status').should('eq', 403);
        cy.login('inactive');
        cy.request({ url: '/staff/', failOnStatusCode: false }).its('status').should('eq', 403);
        cy.assertNoBusinessChange(before);
      });
    });
  });
});

describe('Staff sign-in and sign-out', () => {
  it('Missing, wrong, unassigned and inactive-barber credentials → no shop session or business changes', () => {
    cy.visit('/staff/login/?lang=en');
    cy.task('db:snapshot').then((before) => {
      submit('Sign in');
      cy.get('[name="username"]').then(($input) => expect($input[0].validity.valueMissing).to.eq(true));
      cy.get('[name="username"]').type('owner');
      submit('Sign in');
      cy.get('[name="password"]').then(($input) => expect($input[0].validity.valueMissing).to.eq(true));
      cy.get('[name="password"]').type('Incorrect-synthetic-password', { log: false });
      submit('Sign in');
      cy.contains('Please enter a correct username and password.').should('be.visible');
      cy.assertNoBusinessChange(before);
      cy.env(['auditPassword']).then(({ auditPassword }) => {
        for (const username of ['outsider', 'inactive']) {
          cy.get('[name="username"]').clear().type(username);
          cy.get('[name="password"]').type(auditPassword, { log: false });
          submit('Sign in');
          cy.contains('This account has no shop access.').should('be.visible');
          cy.location('pathname').should('eq', '/staff/login/');
          cy.assertNoBusinessChange(before);
        }
      });
    });
  });

  for (const role of ['owner', 'alan']) {
    it(`${role}: valid credentials → role dashboard, sign out → protected page returns to login`, () => {
      cy.visit('/staff/login/?lang=en&next=https://example.invalid/');
      cy.task('db:snapshot').then((before) => {
        cy.get('[name="username"]').type(role);
        cy.env(['auditPassword']).then(({ auditPassword }) => {
          cy.get('[name="password"]').type(auditPassword, { log: false });
        });
        submit('Sign in');
        cy.location('pathname').should('eq', '/staff/');
        cy.contains('a', role === 'owner' ? 'Manage services' : 'My services').should('be.visible');
        cy.contains('button', 'Sign out').click();
        cy.location('pathname').should('eq', '/');
        cy.visit('/staff/');
        cy.location('pathname').should('eq', '/staff/login/');
        cy.assertNoBusinessChange(before);
      });
    });
  }

  // These intentionally repeated form navigations exceed Cypress's default
  // redirect guard; the application must still answer only request 21 with 429.
  it('Twenty-one rejected sign-in submissions → rate-limit page and no business changes', { redirectionLimit: 30 }, () => {
    cy.visit('/staff/login/?lang=en');
    cy.intercept('POST', '/staff/login/*').as('loginAttempt');
    cy.task('db:snapshot').then((before) => {
      for (let attempt = 1; attempt <= 21; attempt += 1) {
        cy.get('[name="username"]').clear().type('unknown-audit-account');
        cy.get('[name="password"]').type('Incorrect-synthetic-password', { log: false });
        submit('Sign in');
        cy.wait('@loginAttempt').its('response.statusCode').should('eq', attempt === 21 ? 429 : 200);
      }
      cy.contains('Too many attempts. Please try again later.').should('be.visible');
      cy.get('[name="password"]').should('not.exist');
      cy.assertNoBusinessChange(before);
    });
  });
});

describe('Staff schedule mutations and guards', () => {
  it('Single day off and range limit → required date blocks submit, 367 days reject, one date saves', () => {
    openStaff('alan');
    cy.get('@seed').then((seed) => {
      cy.visit(`/staff/barbers/${seed.barbers.alan}/hours/`);
      cy.task('db:snapshot').then((before) => {
        submit('Add days off');
        cy.get('[name="date"]').then(($input) => expect($input[0].validity.valueMissing).to.eq(true));
        cy.assertNoBusinessChange(before);
        const end = new Date(`${seed.nextDate}T12:00:00Z`);
        end.setUTCDate(end.getUTCDate() + 366);
        cy.get('[name="date"]').type(seed.nextDate);
        cy.get('[name="end_date"]').type(end.toISOString().slice(0, 10));
        submit('Add days off');
        cy.contains('Choose at most 366 days').should('be.visible');
        cy.assertNoBusinessChange(before);
        cy.get('[name="end_date"]').clear();
        submit('Add days off');
        cy.contains('Schedule saved.').should('be.visible');
        cy.task('db:snapshot').then((after) => {
          unchangedExcept(before, after, ['daysOff']);
          expect(after.daysOff.filter((row) => row.barber_id === seed.barbers.alan).map((row) => row.date)).to.deep.equal([seed.nextDate]);
        });
      });
    });
  });

  for (const role of ['owner', 'alan']) {
    it(`${role}: cancel own appointment → one cancellation, retained record, repeat is idempotent`, () => {
      openStaff(role);
      cy.get('@seed').then((seed) => {
        cy.task('db:snapshot').then((before) => {
          cy.visit(`/staff/schedule/?date=${seed.date}&view=day`);
          cy.get(`form[action="/staff/appointments/${seed.appointments.alan.id}/cancel/"] button`).click();
          cy.location('pathname').should('eq', '/staff/schedule/');
          cy.contains('Appointment cancelled.').should('be.visible');
          cy.task('db:snapshot').then((after) => {
            unchangedExcept(before, after, ['appointments']);
            expect(after.appointments).to.have.length(before.appointments.length);
            const appointment = after.appointments.find((row) => row.id === seed.appointments.alan.id);
            expect(appointment.cancelled_at).to.be.a('string');
            expect({ ...appointment, cancelled_at: null }).to.deep.equal(before.appointments.find((row) => row.id === appointment.id));
            expect(after.appointments.find((row) => row.id === seed.appointments.boris.id)).to.deep.equal(before.appointments.find((row) => row.id === seed.appointments.boris.id));
            cy.getCookie('csrftoken').then(({ value }) => {
              cy.request({ method: 'POST', url: `/staff/appointments/${appointment.id}/cancel/`, form: true, body: { csrfmiddlewaretoken: value } });
            });
            cy.assertNoBusinessChange(after);
          });
        });
      });
    });
  }

  it('Weekly hours: invalid, conflicting, then valid shifts → atomic rejection or only target shifts replaced', () => {
    openStaff('alan');
    cy.get('@seed').then((seed) => {
      cy.visit(`/staff/barbers/${seed.barbers.alan}/hours/`);
      cy.task('db:snapshot').then((before) => {
        cy.get(`[name="start_${seed.weekday}"]`).clear().type('18:00');
        submit('Save weekly hours');
        cy.contains('Each working day needs a start before its end.').should('be.visible');
        cy.assertNoBusinessChange(before);
        cy.get(`[name="start_${seed.weekday}"]`).clear().type('13:00');
        submit('Save weekly hours');
        cy.contains('Existing appointments conflict with this change.').should('be.visible');
        cy.assertNoBusinessChange(before);
        cy.get(`[name="start_${seed.weekday}"]`).clear().type('10:00');
        cy.get(`[name="end_${seed.weekday}"]`).clear().type('16:00');
        submit('Save weekly hours');
        cy.contains('Schedule saved.').should('be.visible');
        cy.task('db:snapshot').then((after) => {
          unchangedExcept(before, after, ['hours']);
          expect(after.hours.filter((row) => row.barber_id !== seed.barbers.alan)).to.deep.equal(before.hours.filter((row) => row.barber_id !== seed.barbers.alan));
          const shift = after.hours.find((row) => row.barber_id === seed.barbers.alan && row.weekday === seed.weekday);
          expect(shift.opens_at).to.eq('10:00:00');
          expect(shift.closes_at).to.eq('16:00:00');
          expect(after.hours.filter((row) => row.barber_id === seed.barbers.alan)).to.have.length(7);
        });
      });
    });
  });

  it('Days off: conflicts and reversed ranges reject, inclusive range adds once, removal affects one date', () => {
    openStaff('alan');
    cy.get('@seed').then((seed) => {
      cy.visit(`/staff/barbers/${seed.barbers.alan}/hours/`);
      cy.task('db:snapshot').then((before) => {
        cy.get('[name="date"]').type(seed.date);
        submit('Add days off');
        cy.contains('Existing appointments conflict').should('be.visible');
        cy.assertNoBusinessChange(before);
        cy.get('[name="date"]').clear().type(seed.laterDate);
        cy.get('[name="end_date"]').type(seed.nextDate);
        submit('Add days off');
        cy.contains('End date must be on or after start date.').should('be.visible');
        cy.assertNoBusinessChange(before);
        cy.get('[name="date"]').clear().type(seed.nextDate);
        cy.get('[name="end_date"]').clear().type(seed.laterDate);
        submit('Add days off');
        cy.contains('Schedule saved.').should('be.visible');
        cy.task('db:snapshot').then((added) => {
          unchangedExcept(before, added, ['daysOff']);
          expect(added.daysOff.filter((row) => row.barber_id === seed.barbers.alan)).to.have.length(4);
          cy.get('form input[name="action"][value="add_off"]').parent().within(() => {
            cy.get('[name="date"]').type(seed.nextDate);
            cy.get('[name="end_date"]').type(seed.laterDate);
            cy.contains('button', 'Add days off').click();
          });
          cy.contains('Schedule saved.').should('be.visible');
          cy.assertNoBusinessChange(added);
          cy.get(`form input[name="action"][value="remove_off"]`).parent().filter(`:has(input[name="date"][value="${seed.nextDate}"])`).find('button').click();
          cy.contains('Schedule saved.').should('be.visible');
          cy.task('db:snapshot').then((removed) => {
            unchangedExcept(added, removed, ['daysOff']);
            expect(removed.daysOff).to.deep.equal(added.daysOff.filter((row) => !(row.barber_id === seed.barbers.alan && row.date === seed.nextDate)));
          });
        });
      });
    });
  });

  it('My services: save unchanged, clear all, restore active selection → only own assignments change', () => {
    openStaff('alan');
    cy.get('@seed').then((seed) => {
      cy.visit('/staff/my-services/');
      cy.task('db:snapshot').then((before) => {
        submit('Save services');
        cy.contains('Services saved.').should('be.visible');
        cy.assertNoBusinessChange(before);
        cy.get('[name="services"]').uncheck();
        submit('Save services');
        cy.contains('Services saved.').should('be.visible');
        cy.get(`[name="services"][value="${seed.services.inactive}"]`).should('not.exist');
        cy.task('db:snapshot').then((cleared) => {
          unchangedExcept(before, cleared, ['assignments']);
          expect(cleared.assignments.filter((row) => row.barber_id === seed.barbers.alan)).to.have.length(0);
          expect(cleared.assignments.filter((row) => row.barber_id !== seed.barbers.alan)).to.deep.equal(before.assignments.filter((row) => row.barber_id !== seed.barbers.alan));
          cy.visit('/staff/');
          cy.contains('Setup needed · assign an active service').should('be.visible');
          cy.contains('a', 'My services').click();
          cy.get(`[name="services"][value="${seed.services.beard}"]`).check();
          submit('Save services');
          cy.contains('Services saved.').should('be.visible');
          cy.task('db:snapshot').then((restored) => {
            unchangedExcept(before, restored, ['assignments']);
            expect(restored.assignments.filter((row) => row.barber_id === seed.barbers.alan).map((row) => row.service_id)).to.deep.equal([seed.services.beard]);
          });
        });
      });
    });
  });
});

describe('Owner catalogue and account mutations', () => {
  it('Reset barber password → hash changes, old password fails and replacement signs in', () => {
    openStaff();
    cy.get('@seed').then((seed) => {
      cy.visit(`/staff/barbers/${seed.barbers.alan}/`);
      cy.task('db:snapshot').then((before) => {
        cy.env(['auditPassword']).then(({ auditPassword }) => {
          const replacement = `${auditPassword}Replacement`;
          cy.get('[name="password"]').type(replacement, { log: false });
          cy.get('[name="password_confirm"]').type(replacement, { log: false });
          submit('Save barber');
          cy.contains('Profile saved.').should('be.visible');
          cy.task('db:snapshot').then((after) => {
            unchangedExcept(before, after, ['users']);
            const user = after.users.find((row) => row.username === 'alan');
            const oldUser = before.users.find((row) => row.username === 'alan');
            expect(user.password).not.to.eq(oldUser.password);
            expect({ ...user, password: oldUser.password }).to.deep.equal(oldUser);
            cy.contains('button', 'Sign out').click();
            cy.visit('/staff/login/?lang=en');
            cy.get('[name="username"]').type('alan');
            cy.get('[name="password"]').type(auditPassword, { log: false });
            submit('Sign in');
            cy.location('pathname').should('eq', '/staff/login/');
            cy.contains('Please enter a correct username and password.').should('be.visible');
            cy.get('[name="password"]').type(replacement, { log: false });
            submit('Sign in');
            cy.location('pathname').should('eq', '/staff/');
            cy.contains('a', 'My services').should('be.visible');
            cy.assertNoBusinessChange(after);
          });
        });
      });
    });
  });

  it('Service add/edit: required fields, invalid bounds and duplicate name reject; valid edits preserve appointment snapshots', () => {
    openStaff();
    cy.get('@seed').then((seed) => {
      cy.visit('/staff/services/');
      cy.contains('a', 'Add service').click();
      cy.task('db:snapshot').then((before) => {
        submit('Save service');
        cy.get('[name="name"]').then(($input) => expect($input[0].validity.valueMissing).to.eq(true));
        cy.assertNoBusinessChange(before);
        cy.get('[name="name"]').type('Audit Haircut');
        cy.get('[name="duration_minutes"]').type('0');
        cy.get('[name="price"]').type('-1');
        submit('Save service');
        // Django's PositiveIntegerField renders native min=0; its minimum-one
        // model validator correctly rejects zero on the server instead.
        cy.contains('Ensure this value is greater than or equal to 1.').should('be.visible');
        cy.contains('Ensure this value is greater than or equal to 0.00.').should('be.visible');
        cy.assertNoBusinessChange(before);
        cy.get('[name="duration_minutes"]').clear().type('45');
        cy.get('[name="price"]').clear().type('35.50');
        submit('Save service');
        cy.contains('already exists').should('be.visible');
        cy.assertNoBusinessChange(before);
        cy.get('[name="name"]').clear().type('Audit New Service');
        cy.get('[name="name_bg"]').type('Тестова нова услуга');
        cy.get('[name="description"]').type('Synthetic description');
        cy.get('[name="description_bg"]').type('Тестово описание');
        submit('Save service');
        cy.location('pathname').should('eq', '/staff/services/');
        cy.contains('Audit New Service').should('be.visible');
        cy.task('db:snapshot').then((created) => {
          unchangedExcept(before, created, ['services']);
          expect(created.services).to.have.length(before.services.length + 1);
          const service = created.services.find((row) => row.name === 'Audit New Service');
          expect(service).to.include({ duration_minutes: 45, price: '35.50', name_bg: 'Тестова нова услуга', is_active: true });
          cy.get(`a[href="/staff/services/${seed.services.cut}/"]`).click();
          cy.get('[name="duration_minutes"]').clear().type('60');
          cy.get('[name="price"]').clear().type('99.00');
          cy.get('[name="display_order"]').clear().type('8');
          cy.get('[name="is_active"]').uncheck();
          submit('Save service');
          cy.contains('Service saved.').should('be.visible');
          cy.task('db:snapshot').then((edited) => {
            unchangedExcept(created, edited, ['services']);
            expect(edited.services.find((row) => row.id === seed.services.cut)).to.include({ duration_minutes: 60, price: '99.00', display_order: 8, is_active: false });
          });
        });
      });
    });
  });

  it('Add barber: mismatched and duplicate credentials reject; account, assignments and initial shifts save together', () => {
    openStaff();
    cy.visit('/staff/');
    cy.contains('a', 'Add barber').click();
    cy.task('db:snapshot').then((before) => {
      cy.get('[name="username"]').type('audit-new');
      cy.get('[name="name"]').type('Audit New Barber');
      cy.env(['auditPassword']).then(({ auditPassword }) => {
        cy.get('[name="password"]').type(auditPassword, { log: false });
        cy.get('[name="password_confirm"]').type('Mismatch', { log: false });
        submit('Save barber');
        cy.contains('Passwords do not match.').should('be.visible');
        cy.assertNoBusinessChange(before);
        cy.get('[name="username"]').clear().type('alan');
        cy.get('[name="password"]').type(auditPassword, { log: false });
        cy.get('[name="password_confirm"]').type(auditPassword, { log: false });
        submit('Save barber');
        cy.contains('Username already exists.').should('be.visible');
        cy.assertNoBusinessChange(before);
        cy.get('[name="username"]').clear().type('audit-new');
        cy.get('[name="password"]').type(auditPassword, { log: false });
        cy.get('[name="password_confirm"]').type(auditPassword, { log: false });
        cy.get('[name="open_6"]').uncheck();
        submit('Save barber');
        cy.location('pathname').should('eq', '/staff/');
        cy.contains('Audit New Barber').should('be.visible');
        cy.task('db:snapshot').then((after) => {
          unchangedExcept(before, after, ['users', 'barbers', 'assignments', 'hours']);
          expect(after.users).to.have.length(before.users.length + 1);
          const user = after.users.find((row) => row.username === 'audit-new');
          expect(user).to.include({ is_active: true, is_staff: false, is_superuser: false });
          expect(user.password).not.to.eq(auditPassword);
          const barber = after.barbers.find((row) => row.user_id === user.id);
          expect(barber.name).to.eq('Audit New Barber');
          expect(after.hours.filter((row) => row.barber_id === barber.id)).to.have.length(6);
          expect(after.assignments.filter((row) => row.barber_id === barber.id)).to.have.length(2);
          expect(after.hours.filter((row) => row.barber_id === barber.id).every((row) => row.opens_at === '10:00:00' && row.closes_at === '20:00:00')).to.eq(true);
        });
      });
    });
  });

  it('Edit barber: blank password preserves hash and deactivation retains bookings while blocking public selection', () => {
    openStaff();
    cy.get('@seed').then((seed) => {
      cy.visit(`/staff/barbers/${seed.barbers.alan}/`);
      cy.task('db:snapshot').then((before) => {
        cy.get('[name="name"]').clear().type('Audit Alan Updated');
        cy.get('[name="is_active"]').uncheck();
        submit('Save barber');
        cy.contains('Inactive · appointments retained').should('be.visible');
        cy.task('db:snapshot').then((after) => {
          unchangedExcept(before, after, ['users', 'barbers']);
          const user = after.users.find((row) => row.username === 'alan');
          expect(user.is_active).to.eq(false);
          expect(user.password).to.eq(before.users.find((row) => row.username === 'alan').password);
          expect(after.barbers.find((row) => row.id === seed.barbers.alan)).to.include({ is_active: false, name: 'Audit Alan Updated' });
          cy.visit('/book/');
          cy.get(`#visit-selection [name="barber"] option[value="${seed.barbers.alan}"]`).should('not.exist');
          cy.visit(`/staff/schedule/?date=${seed.date}`);
          cy.contains('Synthetic alan client').should('be.visible');
          cy.assertNoBusinessChange(after);
        });
      });
    });
  });

  it('Audit finding: a barber with active services and no working hours still says Accepting bookings', () => {
    openStaff();
    cy.get('@seed').then((seed) => {
      // Inactive fixture has no appointments, so closing all days is permitted.
      cy.visit(`/staff/barbers/${seed.barbers.inactive}/`);
      cy.get('[name="is_active"]').check();
      submit('Save barber');
      cy.visit(`/staff/barbers/${seed.barbers.inactive}/hours/`);
      cy.get('[name^="open_"]').uncheck();
      submit('Save weekly hours');
      cy.contains('Schedule saved.').should('be.visible');
      cy.task('db:snapshot').then((after) => {
        expect(after.hours.filter((row) => row.barber_id === seed.barbers.inactive)).to.have.length(0);
      });
      cy.visit('/staff/');
      cy.contains('article', 'Inactive Barber').should('contain', 'Accepting bookings');
      cy.visit('/book/');
      cy.get(`#visit-selection [name="barber"] option[value="${seed.barbers.inactive}"]`).should('not.exist');
    });
  });

  it('Audit finding: confirmation-only password edit reports saved but preserves the existing password', () => {
    openStaff();
    cy.get('@seed').then((seed) => {
      cy.visit(`/staff/barbers/${seed.barbers.alan}/`);
      cy.task('db:snapshot').then((before) => {
        cy.env(['auditPassword']).then(({ auditPassword }) => {
          cy.get('[name="password_confirm"]').type(`${auditPassword}changed`, { log: false });
        });
        submit('Save barber');
        cy.contains('Profile saved.').should('be.visible');
        cy.assertNoBusinessChange(before);
      });
    });
  });
});
